+                        assertNotNull("engine is null for " + indexService.index().getName(), engine);
+                        assertThat(engine.getEngineConfig().getCodec().getName(), equalTo("FastDecompressionCompressingStoredFieldsData"));
+                    }
+                });
+            }
+        }
+    }
