+
+  - do:
+      index:
+        index:  mlt_one_shard_test_index
+        id:     "1"
+        body:   { foo: bar }
+
+  - do:
+      index:
+        index:  mlt_one_shard_test_index
+        id:     "2"
+        body:   { foo: baz }
+
+  - do:
+      index:
+        index:  mlt_one_shard_test_index
+        id:     "3"
+        body:   { foo: foo }
+
+  - do:
+      indices.refresh: {}
+
+  - do:
+      get:
+        index: mlt_one_shard_test_index
+        id: "1"
+
+  - match: { _source.foo: "bar" }
+
+  - do:
+      get:
+        index: mlt_one_shard_test_index
+        id: "2"
+
+  - match: { _source.foo: "baz" }
+
+  - do:
+      get:
+        index: mlt_one_shard_test_index
+        id: "3"
+
+  - match: { _source.foo: "foo" }
+
+  - do:
+      search:
+        rest_total_hits_as_int: true
+        index:   mlt_one_shard_test_index
