+                for (int j = 0; j < 5; j++) {
+                    tokens.add(new SparseEmbeddingResults.WeightedToken(Integer.toString(j), (float) j));
+                }
+                embeddings.add(new SparseEmbeddingResults.Embedding(tokens, false));
+            }
+            return new SparseEmbeddingResults(embeddings);
+        }
